'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isInfinitef = require( '@stdlib/math/base/assert/is-infinitef' );
var frexpf = require( '@stdlib/math/base/special/frexpf' );
var ldexpf = require( '@stdlib/math/base/special/ldexpf' );
var absf = require( '@stdlib/math/base/special/absf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Rounds a single-precision floating-point number to the nearest power of two on a linear scale.
*
* @param {number} x - input value
* @returns {number} rounded value
*
* @example
* var v = round2f( 3.1415926 );
* // returns 4.0
*
* @example
* var v = round2f( 13.0 );
* // returns 16.0
*
* @example
* var v = round2f( -0.314 );
* // returns -0.25
*
* @example
* var v = round2f( -0.0 );
* // returns -0.0
*/
function round2f( x ) {
	var frac;
	var out;
	var exp;
	var y;

	x = f32( x );
	if ( isnanf( x ) || isInfinitef( x ) || x === 0.0 ) {
		return x;
	}
	// Decompose `|x|` into a normalized fraction and an integer power of two (i.e., `|x| = frac * 2^exp`, where `frac` is on the interval `[0.5, 1)`):
	out = frexpf( absf( x ) );
	frac = out[ 0 ];
	exp = out[ 1 ];

	// Find the closest power of two (note: the previous and next integer powers of two are `2^(exp-1)` and `2^exp`, respectively, and the linear midpoint between them corresponds to `frac == 0.75`; as both the fraction and the midpoint are exactly representable, the comparison is exact, with ties rounding to the next integer power of two):
	if ( frac < 0.75 ) {
		y = ldexpf( 1.0, exp-1 );
	} else {
		// Note: for `|x| >= 1.5 * 2^127`, the next integer power of two (`2^128`) exceeds the maximum single-precision floating-point number, and the result overflows to infinity:
		y = ldexpf( 1.0, exp );
	}
	return ( x < 0.0 ) ? f32( -y ) : y;
}


// EXPORTS //

module.exports = round2f;
